import { Component, signal } from '@angular/core';
import { Text, View } from '@ng-native/components';
import type { NeuOption } from '@neural-ui/native';
import { NeuDataViewComponent } from '@neural-ui/native/data-view';

@Component({
  selector: 'native-collection-example',
  imports: [Text, View, NeuDataViewComponent],
  template: `
    <view class="content">
      <text class="heading">The people behind it.</text>
      <text class="muted">Find a teammate, change the order or refresh this local list.</text>
      <neu-data-view [items]="people" [(query)]="query" [(descending)]="descending"
        searchLabel="Search people" sortLabel="Reverse name order" refreshLabel="Refresh local list"
        emptyLabel="No people match your search" (selected)="select($event)" (refresh)="refresh()" />
      <text class="muted">{{ feedback() }}</text>
    </view>
  `,
  styles: `
    .content { padding: 20px; gap: 16px; }
    .heading { font-size: 26px; font-weight: 700; color: var(--neu-text); }
    .muted { font-size: 14px; color: var(--neu-muted); }
  `,
})
export class NativeCollectionsExample {
  readonly query = signal('');
  readonly descending = signal(false);
  readonly feedback = signal('Choose a person to see their name.');
  readonly people: readonly NeuOption[] = [
    { id: 'ada', label: 'Ada Lovelace', description: 'Product designer' },
    { id: 'grace', label: 'Grace Hopper', description: 'Mobile engineer' },
    { id: 'linus', label: 'Linus Torvalds', description: 'Platform engineer' },
  ];
  select(id: string): void {
    this.feedback.set(`Selected: ${this.people.find(person => person.id === id)?.label ?? id}`);
  }
  refresh(): void {
    this.query.set('');
    this.feedback.set('Local list refreshed. No server request was made.');
  }
}

import { Component, signal } from '@angular/core';
import { Text, View } from '@ng-native/components';
import type { NeuOption } from '@neural-ui/native';
import { NeuButtonComponent } from '@neural-ui/native/button';
import { NeuCheckboxComponent } from '@neural-ui/native/checkbox';
import { NeuInputComponent } from '@neural-ui/native/input';
import { NeuSelectComponent } from '@neural-ui/native/select';

@Component({
  selector: 'native-profile-example',
  imports: [Text, View, NeuButtonComponent, NeuCheckboxComponent, NeuInputComponent, NeuSelectComponent],
  template: `
    <view class="content">
      <text class="eyebrow">YOUR WORKSPACE</text>
      <text class="heading">Make it yours.</text>
      <text class="muted">A name and a team to help everyone find you.</text>
      <neu-input label="Full name" [(value)]="name" [required]="true" hint="Visible to your teammates" />
      <neu-select label="Team" [options]="teams" [(value)]="team" closeLabel="Close teams" />
      <neu-checkbox label="Send me product updates" [(checked)]="updates" />
      <neu-button label="Save profile" [fullWidth]="true" (pressed)="save()" />
      <text class="muted">{{ feedback() }}</text>
    </view>
  `,
  styles: `
    .content { padding: 20px; gap: 16px; }
    .eyebrow { font-size: 12px; color: var(--neu-muted); }
    .heading { font-size: 28px; font-weight: 700; color: var(--neu-text); }
    .muted { font-size: 14px; color: var(--neu-muted); }
  `,
})
export class NativeFormsExample {
  readonly name = signal('Ada Lovelace');
  readonly team = signal('design');
  readonly updates = signal(false);
  readonly feedback = signal('Changes stay in this example.');
  readonly teams: readonly NeuOption[] = [
    { id: 'design', label: 'Design', description: 'Product interfaces' },
    { id: 'engineering', label: 'Engineering', description: 'Application development' },
  ];
  save(): void {
    this.feedback.set(this.name().trim() ? `Saved locally: ${this.name().trim()}` : 'Enter your name.');
  }
}

import { Component, signal } from '@angular/core';
import { Text, View } from '@ng-native/components';
import { NeuCardComponent } from '@neural-ui/native/card';
import { NeuNavComponent, type NeuNavItem } from '@neural-ui/native/nav';

@Component({
  selector: 'native-navigation-example',
  imports: [Text, View, NeuCardComponent, NeuNavComponent],
  template: `
    <view class="screen">
      <view class="body">
        @switch (destination()) {
          @case ('projects') {
            <text class="heading">Room for the next idea.</text>
            <neu-card title="Mobile launch" description="Design review ready">
              <text class="muted">Three screens to review with your team.</text>
            </neu-card>
          }
          @case ('account') {
            <text class="heading">Your workspace profile.</text>
            <neu-card title="Ada Lovelace" description="Product designer">
              <text class="muted">Design team · Notifications enabled</text>
            </neu-card>
          }
          @default {
            <text class="heading">A good day to make something.</text>
            <neu-card title="Today" description="Your team is in sync">
              <text class="muted">Two reviews complete. One new idea to explore.</text>
            </neu-card>
          }
        }
      </view>
      <neu-nav label="Workspace destinations" [items]="destinations" [(value)]="destination" />
    </view>
  `,
  styles: `
    :host, .screen { flex: 1; }
    .body { flex: 1; padding: 20px; gap: 20px; }
    .heading { font-size: 28px; font-weight: 700; color: var(--neu-text); }
    .muted { font-size: 15px; color: var(--neu-muted); }
  `,
})
export class NativeNavigationExample {
  readonly destination = signal('home');
  readonly destinations: readonly NeuNavItem[] = [
    { id: 'home', label: 'Home' },
    { id: 'projects', label: 'Projects' },
    { id: 'account', label: 'Account' },
  ];
}

import { Component, signal } from '@angular/core';
import { Text, View } from '@ng-native/components';
import { NeuButtonComponent } from '@neural-ui/native/button';
import { NeuModalComponent, NeuModalFooterDirective } from '@neural-ui/native/modal';

@Component({
  selector: 'native-overlay-example',
  imports: [Text, View, NeuButtonComponent, NeuModalComponent, NeuModalFooterDirective],
  template: `
    <view class="content">
      <text class="heading">One place for your team.</text>
      <text class="muted">A short explanation, with an explicit way back.</text>
      <neu-button label="About this workspace" (pressed)="open.set(true)" />
      <text class="muted">{{ feedback() }}</text>
      <neu-modal title="Product workspace" [(open)]="open" closeLabel="Close workspace details"
        (closed)="feedback.set('Workspace details closed.')">
        <text class="message">A shared place for your team's plans and documents.</text>
        <ng-template neuModalFooter>
          <neu-button label="Got it" size="sm" (pressed)="open.set(false)" />
        </ng-template>
      </neu-modal>
    </view>
  `,
  styles: `
    .content { padding: 20px; gap: 16px; }
    .heading { font-size: 26px; font-weight: 700; color: var(--neu-text); }
    .message { font-size: 16px; color: var(--neu-text); }
    .muted { font-size: 14px; color: var(--neu-muted); }
  `,
})
export class NativeOverlaysExample {
  readonly open = signal(false);
  readonly feedback = signal('Details are closed.');
}

import { Component, computed, signal } from '@angular/core';
import { Text, View } from '@ng-native/components';
import type { NeuTokens } from '@neural-ui/native/foundation';
import { NeuThemeComponent } from '@neural-ui/native/theme';
import { NeuSwitchComponent } from '@neural-ui/native/switch';
import { NeuCardComponent } from '@neural-ui/native/card';
import { NeuButtonComponent } from '@neural-ui/native/button';

@Component({
  selector: 'native-theme-example',
  imports: [Text, View, NeuThemeComponent, NeuSwitchComponent, NeuCardComponent, NeuButtonComponent],
  template: `
    <neu-theme [scheme]="dark() ? 'dark' : 'light'" [tokens]="brand()">
      <view class="content">
        <text class="heading">A little more you.</text>
        <neu-switch label="Dark appearance" [(checked)]="dark" />
        <neu-card title="Neural, with your palette" description="Shared tokens, real controls">
          <view class="card-content">
            <text class="muted">Readable surfaces and controls in both appearances.</text>
            <neu-button label="Try the brand color" (pressed)="feedback.set('Brand action pressed.')" />
          </view>
        </neu-card>
        <text class="muted">{{ feedback() }}</text>
      </view>
    </neu-theme>
  `,
  styles: `
    .content { padding: 20px; gap: 16px; background-color: var(--neu-canvas); }
    .card-content { gap: 16px; }
    .heading { font-size: 28px; font-weight: 700; color: var(--neu-text); }
    .muted { font-size: 14px; color: var(--neu-muted); }
  `,
})
export class NativeThemeExample {
  readonly dark = signal(false);
  readonly feedback = signal('Switch appearance to compare the palette.');
  readonly brand = computed(() => ({
    accent: this.dark() ? '#b9b1ff' : '#5941c6',
    onAccent: this.dark() ? '#23164b' : '#ffffff',
    radius: 16,
  } satisfies Partial<NeuTokens>));
}
